 EquipmentDef[] InteractionSelectionEquipment(Result cfg){if(!cfg.originalInteractionSelection)return new EquipmentDef[0];var def=artifactBundle.LoadAsset<EquipmentDef>(cfg.recycleAsset);Check(def&&def.name=="Recycle"&&def.unlockableDef&&!def.requiredExpansion,"Original Recycle comparison contract changed");BindEnemyDefinition(typeof(RoR2Content.Equipment),"Recycle",def);return new[]{def};}
