   r.interactionSelection.seconds=Time.realtimeSinceStartup-began;r.interactionSelection.fixedTicks=r.runClock.fixedTicks-fixedBegan;r.interactionSelection.cooldownSeconds=cooldown-(float)DriverField(driver,"interactableCooldown");r.interactionSelection.automatic=r.interactionSelection.frames>50&&r.interactionSelection.fixedTicks>100&&Mathf.Abs(r.interactionSelection.cooldownSeconds-r.interactionSelection.fixedTicks*Time.fixedDeltaTime)<.05f;Check(r.interactionSelection.automatic,"Original automatic interaction callback intervals differ");
