   CleanupOriginalBarrel();yield return null;yield return null;Call(activeBodyClient,"Update");r.interactionSelection.targetRemoved=!barrelObject&&!barrelModel&&!barrelPreview&&!driver.currentInteractable;Check(r.interactionSelection.targetRemoved,"Original target destruction/selection removal incomplete");
